pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Bank b1;
    Bank b2;

    function setUp() public {
        c = new C();
        b1 = new Bank();
        b2 = new Bank();
    }

    function testFuzz_property(uint256 chooser) public {
        chooser = bound(chooser, 0, type(uint256).max);
        // the fuzzed chooser selects which admissible counterparty (a contract whose
