pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 reentries) public {
        reentries = bound(reentries, 1, 3);
        ReentrantBank attacker = new ReentrantBank();
        attacker.setTarget(address(c));
        attacker.setReentries(reentries);
        bool ok;
        try attacker.attack() { ok = true; } catch { ok = false; }
        // General rule: after any airDrop attempt (reentrant or not), the caller's
        // balance is at most one grant (20). The lockless mutant allows a double grant.
        assertTrue(c.tokenBalance(address(attacker)) <= 20, "double grant");
    }
}

contract ReentrantBank {
    C target;
    uint256 reentries;
    uint256 depth;

    function setTarget(address t) external { target = C(t); }
    function setReentries(uint256 n) external { reentries = n; depth = 0; }

    function attack() external {
        depth = 0;
        target.airDrop();
    }

    function supportsToken() external returns (bytes32) {
        if (depth < reentries) {
            depth++;
            target.airDrop();
        }
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

